R=Path(__file__).parent;B=Path('/workspace/reproduction/neuromuscular/available-chain');O=R/'results/manual-mechanism';O.mkdir(exist_ok=True);rows=list(csv.DictReader((B/'neuron-metadata.csv').open()));axis=list(csv.DictReader((B/'matrix-neuron-IDs.csv').open()));assert [x['bodyId'] for x in rows]==[x['MANC_body_id'] for x in axis];W=sparse.load_npz(B/'MANC-central-connections-20251006.npz').tocsr();types={'DNg100','IN17A001','INXXX466','IN16B036','IN19A007'};core=[i for i,x in enumerate(rows) if x['type'] in types];cross=list(csv.DictReader((R/'data/model-130-channel-candidate-crosswalk.csv').open(encoding='utf-8-sig')));mnids={b for x in cross for b in x['candidate_MANC_body_ids'].split(';') if b};mn=[i for i,x in enumerate(rows) if x['bodyId'] in mnids];coreout=set(W[core].nonzero()[1]);targets=set(W[:,core+mn].nonzero()[0]);bridge=coreout&targets;keep=core+sorted((set(mn)|bridge)-set(core));meta=[rows[i] for i in keep];matrix=W[keep][:,keep];sparse.save_npz(O/'connectivity.npz',matrix);(O/'neurons.json').write_text(json.dumps(meta,indent=2));old=json.load(open(R/'data/all-legs-induced-neurons.json'));oldids={x['bodyId'] for x in old};missing=[x for x in meta[:len(core)] if x['bodyId'] not in oldids];manifest={'source':'author signed MANC matrix 20251006','orientation':'row pre, column post','nodes':len(keep),'edges':matrix.nnz,'source_rhythm_nodes':len(core),'mapped_MN':len(mn),'bridge_rule':'core first hop intersect sources of edges to core or mapped MN; induced context','new_core_nodes_absent_from_previous_induced_graph':missing,'boundary':'not full VNC, no body feedback, no invented wiring','source_matrix_sha256':hashlib.sha256((B/'MANC-central-connections-20251006.npz').read_bytes()).hexdigest(),'data_axis_sha256':hashlib.sha256((B/'matrix-neuron-IDs.csv').read_bytes()).hexdigest()};(O/'network-manifest.json').write_text(json.dumps(manifest,indent=2));print('nodes',len(keep),'core',len(core),'MN',len(mn),'new core',[(x['bodyId'],x['type']) for x in missing])
